<?php

declare(strict_types=1);

$e = static fn(mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$safeUrl = static function (mixed $value): bool {$url=trim((string)$value);return (str_starts_with($url,'/')&&!str_starts_with($url,'//')&&!str_contains($url,'..')&&!preg_match('/[\s<>"\x27\\\\]/u',$url))||(bool)preg_match('/^(?:mailto|tel):[^\s<>]+$/iD',$url)||(bool)preg_match('/^https:\/\/[^\s<>]+$/iD',$url);};
$managed=isset($page['id']);$settings=is_array($themeSettings??null)?$themeSettings:[];$profile=is_array($profile??null)?$profile:[];$seo=is_array($seo??null)?$seo:[];
$title=trim((string)($seo['title']??$page['title']??'School Theme'))?:'School Theme';$description=trim((string)($seo['description']??$page['excerpt']??$page['description']??''));$siteName=trim((string)($seo['site_name']??$profile['name']??'School Theme'))?:'School Theme';$canonical=(string)($seo['canonical']??(($baseUrl??'').'/'));
$primary=(string)($settings['primary_color']??'#163b5c');$accent=(string)($settings['accent_color']??'#d15d45');$surface=(string)($settings['surface_color']??'#f4f1eb');$logo=(string)($settings['logo_url']??$profile['logo']??'');$favicon=(string)($settings['favicon_url']??'');
$primaryMenu=(array)($menu??$navigation['primary']??[]);$footerLinks=(array)($footerMenu??$navigation['footer']??[]);$languageUrls=(array)($languageUrls??[]);$currentPath=(string)parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);$homeUrl=$managed?(string)($languageUrls[$locale]??'/'):'/';$contactLabel=trim((string)($settings['contact_label']??'Contact us'))?:'Contact us';
?>
<!doctype html><html lang="<?= $e($locale??'en') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $e($title) ?> · <?= $e($siteName) ?></title><?php if($description!==''):?><meta name="description" content="<?= $e($description) ?>"><?php endif;?><?php if($canonical!==''):?><link rel="canonical" href="<?= $e($canonical) ?>"><?php endif;?><?php if($favicon!==''&&$safeUrl($favicon)):?><link rel="icon" href="<?= $e($favicon) ?>"><?php endif;?><meta name="theme-color" content="<?= $e($primary) ?>"><link rel="stylesheet" href="/theme-assets/school.css"><script src="/theme-assets/school.js" defer></script><style>:root{--school-primary:<?= $e($primary) ?>;--school-accent:<?= $e($accent) ?>;--school-surface:<?= $e($surface) ?>}</style></head>
<body><a class="school-skip" href="#school-main">Skip to content</a><header class="school-header"><div class="school-shell school-header-inner"><a class="school-brand" href="<?= $e($homeUrl) ?>" aria-label="<?= $e($siteName) ?> home"><?php if($logo!==''&&$safeUrl($logo)):?><img src="<?= $e($logo) ?>" alt="<?= $e($siteName) ?>"><?php else:?><span class="school-mark" aria-hidden="true">S</span><span><?= $e($siteName) ?></span><?php endif;?></a><button class="school-menu-toggle" type="button" aria-expanded="false" aria-controls="school-navigation"><span></span><span></span><span class="school-sr-only">Menu</span></button><nav id="school-navigation" class="school-navigation" aria-label="Primary navigation"><?php foreach($primaryMenu as$item):$url=(string)($item['url']??'');$label=trim((string)($item['label']??''));if($label===''||!$safeUrl($url))continue;?><a href="<?= $e($url) ?>"<?= rtrim(explode('#',$url,2)[0],'/')===rtrim($currentPath,'/')?' aria-current="page"':'' ?>><?= $e($label) ?></a><?php endforeach;?></nav><div class="school-actions"><?php foreach($languageUrls as$code=>$url):if($code===($locale??'')||!$safeUrl($url))continue;?><a class="school-language" href="<?= $e($url) ?>" hreflang="<?= $e($code) ?>" lang="<?= $e($code) ?>"><?= $e(strtoupper((string)$code)) ?></a><?php endforeach;?><?php if(!empty($profile['email'])):?><a class="school-button" href="mailto:<?= $e($profile['email']) ?>"><?= $e($contactLabel) ?></a><?php endif;?></div></div></header><main id="school-main">
<?php if(!$managed):?><section class="school-static-hero"><div class="school-shell"><p class="school-eyebrow">SCHOOL THEME</p><h1><?= $e($title) ?></h1><p><?= $e($description) ?></p></div></section><?php elseif(($contentType??'page')==='post'):?><article class="school-article school-shell"><p class="school-eyebrow">NEWS</p><h1><?= $e($title) ?></h1><?php if($description!==''):?><p class="school-intro"><?= $e($description) ?></p><?php endif;?><div class="school-rich-copy"><?= \App\Core\HtmlSanitizer::sanitize((string)($page['content']??'')) ?></div></article><?php else:?><?php if(empty($page['blocks'])):?><section class="school-page-intro"><div class="school-shell"><p class="school-eyebrow"><?= $e($siteName) ?></p><h1><?= $e($title) ?></h1><?php if($description!==''):?><p><?= $e($description) ?></p><?php endif;?></div></section><?php endif;?><?php require __DIR__.'/views/blocks.php';?><?php endif;?></main><footer class="school-footer"><div class="school-shell school-footer-grid"><div><a class="school-brand" href="<?= $e($homeUrl) ?>"><span class="school-mark" aria-hidden="true">S</span><span><?= $e($siteName) ?></span></a><p><?= $e($profile['tagline']??'A clear, welcoming place to share your school’s story.') ?></p></div><nav aria-label="Footer navigation"><?php foreach($footerLinks as$item):$url=(string)($item['url']??'');$label=trim((string)($item['label']??''));if($label!==''&&$safeUrl($url)):?><a href="<?= $e($url) ?>"><?= $e($label) ?></a><?php endif;endforeach;?></nav><address><?php if(!empty($profile['address'])):?><span><?= nl2br($e($profile['address'])) ?></span><?php endif;?><?php if(!empty($profile['phone'])):?><a href="tel:<?= $e($profile['phone']) ?>"><?= $e($profile['phone']) ?></a><?php endif;?><?php if(!empty($profile['email'])):?><a href="mailto:<?= $e($profile['email']) ?>"><?= $e($profile['email']) ?></a><?php endif;?></address></div></footer></body></html>
